INSERT INTO `sanpham` VALUES ('SP000001','Sửa Rửa Mặt CeraVe Foaming Cleanser','DM000001','TH000001',385000.00,300000.00,13,'Sua-rua-mat-CeraVe-cho-da-dau-Foaming-Facial-Cleanser-473ml.png','Sữa rửa mặt tạo bọt giúp làm sạch dầu thừa và bụi bẩn trên da.','Ceramide, Hyaluronic Acid, Niacinamide','Làm sạch da, hỗ trợ duy trì hàng rào bảo vệ da.',0,20),('SP000002','Kem Dưỡng Ẩm CeraVe Moisturizing Cream','DM000001','TH000001',450000.00,350000.00,25,'kem-duong-am-danh-cho-da-kho-cerave-moisturising-cream-454ml.png','Kem dưỡng ẩm dành cho da khô và da thường.','Ceramide, Hyaluronic Acid','Dưỡng ẩm và hỗ trợ phục hồi hàng rào bảo vệ da.',1,20),('SP000003','Kem Bôi Ngừa mụn La Roche-Posay Effaclar Duo+','DM000001','TH000002',420000.00,330000.00,5,'la-roche-posay-effaclar-duo-corrective-unclogging-care-antiimperfections-anti-marks-anti-reoccurence-40ml.png','Kem dưỡng chăm sóc da dầu và da có khuyết điểm.','Niacinamide, LHA','Hỗ trợ giảm khuyết điểm và chăm sóc da dầu.',1,20),('SP000004','Kem Chống Nắng La Roche-Posay Anthelios UVMune 400','DM000005','TH000002',495000.00,390000.00,15,'kem-chong-nang-la-roche-posay-dang-sua-cho-da-nhay-cam-50ml.png','Kem chống nắng giúp bảo vệ da trước tác động của tia UV.','Mexoryl 400, Glycerin','Bảo vệ da trước tia UVA và UVB.',1,20),('SP000005','Tinh Chất Dưỡng The Ordinary Niacinamide 10% + Zinc 1%','DM000001','TH000003',280000.00,210000.00,34,'the-ordinary-niacinamide-10-zinc-1-30ml.jpg','Tinh chất chăm sóc da với Niacinamide và Zinc.','Niacinamide 10%, Zinc 1%','Hỗ trợ kiểm soát dầu và cải thiện tình trạng da không đều màu.',1,20),('SP000006','Tinh Chất Dưỡng The Ordinary Hyaluronic Acid 2% + B5','DM000001','TH000003',300000.00,225000.00,36,'the-ordinary-hyaluronic-acid.jpg','Tinh chất cấp ẩm cho da.','Hyaluronic Acid 2%, Vitamin B5','Cấp ẩm và giúp da duy trì độ ẩm.',1,20),('SP000007','Kem dưỡng L\'Oréal Revitalift Cream Siêu Cấp Ẩm Căng Mịn Da 50ml','DM000001','TH000004',520000.00,410000.00,8,'kem-duong-loreal-paris-revitalift-hyaluronic-acid-plumping-cream-day-50ml.jpeg','Kem dưỡng da hỗ trợ chăm sóc da trưởng thành.','Pro-Retinol, Hyaluronic Acid','Dưỡng ẩm và hỗ trợ cải thiện dấu hiệu lão hóa.',1,20),('SP000008','Kem nền Maybelline Fit Me Foundation','DM000002','TH000005',235000.00,175000.00,20,'face-make-up_foundation_fit-me-matte-poreless-foundation_Fair-Ivory.jpg','Kem nền trang điểm với nhiều tông màu.','Pigments, Silicones','Giúp tạo lớp nền đều màu và tự nhiên.',0,20),('SP000009','Mascara Maybelline Lash Sensational Waterproof','DM000002','TH000005',210000.00,155000.00,27,'mascara-maybelline-lash-sensational-waterproof-very-black.jpg','Mascara giúp làm dày và tạo độ cong cho hàng mi.','Sáp, Pigments','Tạo độ dày và độ cong cho mi.',1,20),('SP000010','Dầu Gội, Dầu Xả Cao Cấp Dưỡng Ẩm Sâu, Phục Hồi, Nuôi Dưỡng Dove Damage Therapy Shampoo Daily Moisture 532ml','DM000003','TH000006',185000.00,140000.00,18,'dove-dau-goi-daily-moisture.png','Dầu gội chăm sóc tóc và hỗ trợ duy trì độ ẩm.','Glycerin, Moisturizing Agents','Làm sạch tóc và hỗ trợ dưỡng ẩm.',1,20),('SP000011','Sữa Tắm Dưỡng Ẩm Dove Vitality Renewal Serum Body Wash Cho Da Lão Hóa 547ml','DM000004','TH000006',165000.00,120000.00,33,'dove-vitality-renewal-serum-body-wash.png','Sữa tắm giúp làm sạch và dưỡng ẩm da.','Glycerin, Moisturizing Cream','Làm sạch và hỗ trợ duy trì độ ẩm cho da.',1,20),('SP000012','Tinh chất SVR Sebiaclear Serum giảm mụn mờ thâm, làm mịn da (30ml)','DM000001','TH000007',250000.00,200000.00,93,'https://res.cloudinary.com/ddxrieh4l/image/upload/v1789076432/nycosmetics/products/SP000012.png','SVR Sebiaclear Serum với công thức chứa 14% Gluconolactone (PHA) kết hợp với 4% Niacinamide hỗ trợ giảm mụn và làm mờ vết thâm mụn chỉ sau 7 ngày, giúp làm dịu và sáng da. Aroleaf Samphira (tương tự như dẫn xuất Retinoid) + Hyaluronic Acid cải thiện nếp nhăn và dưỡng ẩm cho da lên đến 8 giờ.','Aqua, Gluconolactone, Methyl Methacrylate Crosspolyme, Dicaprylyl Carbonate, Niacinamide, Propanediol, Sodium hydroxide, Dimethicon, Glycerin, Caprylic/capric triglycerides, Cetearyl alcol, Salicylic acid\r\n','Sản phẩm chăm sóc da dạng lỏng hỗ trợ làm mờ vết nám, sạm da, chống nhăn, thông thoáng lỗ chân lông và giúp làm da mềm mịn.\r\n\r\n',1,10),('SP000013','Sữa Rửa Mặt CeraVe Làm Sạch & Tẩy Tế Bào Chết Dịu Nhẹ 473ml','DM000001','TH000001',389000.00,290000.00,44,'sua-rua-mat-lam-sach-sau-tay-da-chet-diu-nhe-cerave-developed-with-dermatologists-sa-smoothing-cleanser-473ml.png','Sữa rửa mặt tạo bọt giúp làm sạch dầu thừa mà vẫn duy trì hàng rào bảo vệ da.','Ceramides, Niacinamide, Hyaluronic Acid','Làm sạch dầu thừa, bụi bẩn và giúp da sạch thoáng.',1,20),('SP000014','Sữa Rửa Mặt Cerave Dưỡng Ẩm, Làm Sạch Sâu Dành Cho Da Thường & Da Khô Hydrating Cleanser 236ml','DM000001','TH000001',399000.00,300000.00,37,'sua-rua-mat-cerave-danh-cho-da-thuong-da-kho-236ml.png','Sữa rửa mặt dịu nhẹ giúp làm sạch và duy trì độ ẩm tự nhiên cho da.','Ceramides, Hyaluronic Acid, Glycerin','Làm sạch nhẹ nhàng và hỗ trợ duy trì độ ẩm cho da.',1,20),('SP000015','Sữa rửa mặt cho da dầu mụn CeraVe Blemish Control Cleanser 236ml','DM000001','TH000001',429000.00,320000.00,34,'cerave-blemish-control-cleanser-236ml.png','Sữa rửa mặt hỗ trợ làm sạch dầu thừa và chăm sóc làn da dễ nổi mụn.','Salicylic Acid, Niacinamide, Ceramides','Làm sạch bã nhờn và hỗ trợ chăm sóc da mụn.',1,20),('SP000016','Sữa Rửa Mặt SVR Sebiaclear Gel Moussant 400ml','DM000001','TH000007',359000.00,270000.00,42,'sua-rua-mat-svr-sebiaclear-gel-moussant-400ml.png','Sữa rửa mặt dịu nhẹ phù hợp sử dụng hằng ngày.','Ceramides, Glycerin, Hyaluronic Acid','Làm sạch bụi bẩn, dầu thừa và dư thừa từ sản phẩm tẩy trang.',1,20),('SP000017','Sữa dưỡng ẩm CeraVe Moisturising Lotion dành cho da thường, da khô và rất khô 236ml','DM000001','TH000001',449000.00,335000.00,39,'sua-duong-cerave-moisturising-lotion-236-ml.png','Sữa dưỡng ẩm giúp bổ sung độ ẩm và hỗ trợ phục hồi hàng rào bảo vệ da.','Ceramides, Hyaluronic Acid, Petrolatum','Dưỡng ẩm và hỗ trợ phục hồi hàng rào bảo vệ da.',1,20),('SP000018','Sữa Dưỡng Ẩm Cho Da Khô CeraVe Intensive Moisturising Lotion','DM000001','TH000001',479000.00,360000.00,36,'sua-duong-am-CeraVe-Intensive-Moisturising-473ml.png','Sữa dưỡng ẩm có kết cấu nhẹ giúp cung cấp độ ẩm cho da mặt và cơ thể.','Hydro-Urea, Ceramides, Hyaluronic Acid, Glycerin','Dưỡng ẩm và giúp giảm và ngăn ngừa năm dấu hiệu chính của da khô - ngứa, căng da, thô ráp, vảy da nhìn thấy được và đỏ hoặc đổi màu da do khô',1,20),('SP000019','Kem Dưỡng Dạng Gel Kiềm Dầu Cho Da Dầu & Hỗn Hợp Cerave Oil Control Moisturising Gel-Cream 52ml','DM000001','TH000001',429000.00,320000.00,27,'cerave-oil-control-gel.png','Gel dưỡng có kết cấu mỏng nhẹ giúp kiểm soát dầu và duy trì độ ẩm.','Ceramides, Niacinamide, Hyaluronic Acid','Dưỡng ẩm, hỗ trợ kiểm soát dầu và phục hồi hàng rào da.',1,20),('SP000020','Serum CeraVe Phục Hồi Da Với Retinol 30ml','DM000001','TH000001',569000.00,430000.00,28,'serum-cerave-retinol.png','Tinh chất chăm sóc da giúp cải thiện bề mặt da và hỗ trợ làm đều màu da.','Retinol, Ceramides, Niacinamide','Hỗ trợ cải thiện bề mặt da và chăm sóc da không đều màu.',1,20),('SP000021','Sữa Chống Nắng Cerave Kiềm Dầu, Mỏng Nhẹ, Khô Thoáng Invisible Dry Touch Fluid Sunscreen SPF50+ PA++++ 50ml','DM000005','TH000001',459000.00,345000.00,30,'sua-chong-nang-cerave-kiem-dau.png','Sữa chống nắng giúp bảo vệ da trước tia UVA và UVB đồng thời dưỡng ẩm.','Ceramides, Hyaluronic Acid, Zinc Oxide','Bảo vệ da khỏi tác động của tia UV và hỗ trợ dưỡng ẩm.',1,20),('SP000022','Kem Chống Nắng L\'Oreal Mịn Nhẹ, Bảo Vệ Da, Ngăn Ngừa Lão Hóa UV Defender SPF 50+/PA++++ 50ml','DM000005','TH000004',489000.00,365000.00,18,'kem-chong-nang-l-oreal-50ml.png','Kem chống nắng với 2 lớp màng bảo vệ (Màng lọc Mexoryl SX và Mexorul XL) giúp bảo vệ da dưới tác động của tia UVA và UVB cả ngày dài.','Ceramides, Niacinamide, Hyaluronic Acid','Dưỡng ẩm và  giúp bảo vệ da suốt 12h, ngăn ngừa đốm nâu, vết thâm nám, sạm da và lão hóa sớm.',1,20),('SP000023','Gel Rửa Mặt Tạo Bọt Da Dầu La Roche-Posay 400Ml','DM000001','TH000002',379000.00,285000.00,40,'gel-rua-mat-da-dau-nhay-cam-la-roche-posay-effaclar-400ml.png','Gel rửa mặt giúp làm sạch dầu thừa và bụi bẩn trên da.','Zinc, Thermal Spring Water','Làm sạch dầu thừa và giúp da thông thoáng.',1,20),('SP000024','Sữa rửa mặt La Roche-Posay Toleriane Foaming Cream cho mọi loại da 125ml','DM000001','TH000002',389000.00,292000.00,37,'sua-rua-mat-la-roche-posay-toleriane-125ml.png','Gel làm sạch dịu nhẹ phù hợp với làn da nhạy cảm.','Glycerin, Thermal Spring Water','Làm sạch dịu nhẹ và giúp duy trì độ ẩm cho da.',1,20),('SP000025','Kem Dưỡng Giúp Làm Dịu, Giúp Phục Hồi Da La Roche-Posay Cicaplast Baume B5 Từ Công Nghệ Vi Sinh 100ml','DM000001','TH000002',429000.00,320000.00,29,'kem-duong-la-roche-posay-cicaplast-baume-b5-100ml.png','Kem dưỡng hỗ trợ làm dịu và phục hồi làn da khô, nhạy cảm.','Panthenol, Madecassoside, Glycerin','Làm dịu, dưỡng ẩm và hỗ trợ phục hồi da.',1,20),('SP000026','Tinh chất giảm mụn La Roche-Posay Effaclar Ultra Concentrated Serum 30ml','DM000001','TH000002',549000.00,410000.00,21,'tinh-chat-giam-mun-la-roche-posay-effaclar-ultra-concentrated-30ml.png','Tinh chất chăm sóc làn da dầu mụn và hỗ trợ cải thiện khuyết điểm.','Salicylic Acid, Glycolic Acid, Niacinamide','Hỗ trợ giảm mụn, làm sạch lỗ chân lông và cải thiện bề mặt da.',1,20),('SP000027','Kem Dưỡng Ẩm Olay Hỗ Trợ Cải Thiện Lão Hóa Da Regenerist Super Collagen Peptides Soft Moisturiser 45g','DM000001','TH000008',519000.00,390000.00,24,'kem-duong-olay-regenerist-super-collagen-peptides-soft-moisturiser-45g.png','Kem chống nắng giúp bảo vệ da trước tia UVA và UVB.Kết cấu nhẹ, thấm nhanh vào da mà không gây nhờn rít. Được kiểm nghiệm da liễu, phù hợp cho mọi loại da, kể cả da nhạy cảm.','Palmitoyl Pentapeptide-4, Palmitoyl Dipeptide-7, Acetyl Tetrapeptide-11, Tripeptide-3, Acetyl Hexapeptide-8','Hỗ trợ cải thiện và ngăn ngừa các dấu hiệu lão hoa da, thúc đẩy sản sinh collagen tự nhiên cho da, hỗ trợ cải t